//! 小虎 ("little tiger", Kotora's name) as two vector icons, so it draws the same everywhere:
//! Linux without a CJK font installed, macOS, headless snaps. Tinted with `.color()` like the
//! line icons. Each glyph fills one em: a 100 view, baseline at 88.
//!
//! The outlines are Noto Sans JP's (https://github.com/notofonts/noto-cjk, SIL Open Font
//! License 1.1, `assets/kanji/NotoSansJP-OFL.txt`), taken at weights 500 and 700 from the
//! variable font with fontTools and written as SVG paths. Only these two glyphs are used.

use rune::{El, Icon, icon, row};

/// 小虎 `size` points tall (one em per glyph), at weight 500 (`bold`: 700), in `color`.
pub fn name(size: f32, bold: bool, color: rune::Color) -> El {
    let (ko, tora) = if bold {
        (&KO_700, &TORA_700)
    } else {
        (&KO_500, &TORA_500)
    };
    row()
        .role("text")
        .label("\u{5c0f}\u{864e}")
        .child(icon(ko, size).color(color))
        .child(icon(tora, size).color(color))
}

